function renderLegacyUpscaled(
  map: readonly string[],
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): { width: number; height: number; data: Uint8ClampedArray } {
  const size = SPRITE_SIZE;
  const data = new Uint8ClampedArray(size * size * 4);
  const primary = hexToRgb(palette.primary);
  const accent = hexToRgb(palette.accent);
  // 대기 2프레임째는 강조색이 은은히 밝아지는 호흡, 공격 프레임은 강하게 발광
  const accentNow = anim === 'ATTACK' ? lighten(accent, 0.5) : frame % 2 === 1 ? lighten(accent, 0.22) : accent;
  const colors: Record<string, Rgb> = {
    o: OUTLINE_RGB,
    p: primary,
    d: hexToRgb(palette.secondary),
    a: accentNow,
    h: lighten(primary, 0.38),
    w: [244, 246, 255],
    k: [26, 29, 38],
  };
  const flip = dir === 'W' || dir === 'NW' || dir === 'SW';
  const bob = anim === 'WALK' && frame % 2 === 1 ? 1 : 0;
  const ox = 4;
  const oy = 7 - bob;
  const put = (px: number, py: number, c: Rgb): void => {
    if (px < 0 || px >= size || py < 0 || py >= size) {
      return;
    }
    const i = (py * size + px) * 4;
    data[i] = c[0];
    data[i + 1] = c[1];
    data[i + 2] = c[2];
    data[i + 3] = 255;
  };
  for (let y = 0; y < 12; y += 1) {
    const row = (map[y] ?? '').padEnd(12, '.');
    for (let x = 0; x < 12; x += 1) {
      const key = row[x];
      const base = colors[key];
      if (!base) {
        continue;
      }
      const sx = flip ? 11 - x : x;
      for (let dy = 0; dy < 2; dy += 1) {
        for (let dx = 0; dx < 2; dx += 1) {
          const py = oy + y * 2 + dy;
          let c = base;
          if (key !== 'o' && key !== 'w') {
            // 위쪽은 밝게, 아래쪽은 어둡게: 세로 볼륨 램프 + 블록 하단 음영
            const k = (py - oy) / 24;
            c = k < 0.4 ? lighten(base, (0.4 - k) * 0.35) : darken(base, (k - 0.4) * 0.45);
            if (dy === 1) {
              c = darken(c, 0.12);
            }
          }
          put(ox + sx * 2 + dx, py, c);
        }
      }
    }
  }
  if (anim === 'ATTACK') {
    // 바라보는 방향 앞쪽 공격 섬광
    const v = dir8Vector(dir);
    const cx = Math.round(16 + v.dx * 11);
    const cy = Math.round(18 + v.dy * 9) - bob;
    const glow = lighten(accent, 0.7);
    for (let yy = -2; yy <= 2; yy += 1) {
      for (let xx = -2; xx <= 2; xx += 1) {
        if (Math.abs(xx) + Math.abs(yy) <= (frame % 2 === 0 ? 3 : 2)) {
          put(cx + xx, cy + yy, Math.abs(xx) + Math.abs(yy) <= 1 ? [255, 255, 255] : glow);
        }
      }
    }
  }
  return { width: size, height: size, data };
}

/**
 * 순수 함수: 아키타입 + 팔레트 + 프레임 + 8방향(SpriteDir8) + 상태(IDLE|WALK|ATTACK) → 32x32 RGBA 픽셀 버퍼.
 */
export function renderSpritePixels(
  archetype: SpriteArchetype,
  palette: FactionPalette,
  frame: number = 0,
  dir: SpriteDir8 = 'S',
  anim: SpriteAnim = 'IDLE'
): { width: number; height: number; data: Uint8ClampedArray } {
  const f = Math.abs(Math.round(frame));
  const legacy = LEGACY_MAPS[archetype];
  if (legacy) {
    return renderLegacyUpscaled(legacy, palette, f, dir, anim);
  }
  const canvas = new SculptCanvas32();

  switch (archetype) {
    case 'COMMANDER': {
      const kind = detectCommanderFaction(palette);
      if (kind === 'HIVE') {
        drawHiveCommander32(canvas, palette, f, dir, anim);
      } else if (kind === 'LUMEN') {
        drawLumenCommander32(canvas, palette, f, dir, anim);
      } else {
        drawIroncladCommander32(canvas, palette, f, dir, anim);
      }
      break;
    }
    case 'SOLDIER':
      drawSoldier32(canvas, palette, f, dir, anim);
      break;
    case 'FLAMER':
      drawFlamer32(canvas, palette, f, dir, anim);
      break;
    case 'WALKER':
      drawWalker32(canvas, palette, f, dir, anim);
      break;
    case 'DRONE':
      drawDrone32(canvas, palette, f, dir, anim);
      break;
    case 'CLAW':
      drawClaw32(canvas, palette, f, dir, anim);
      break;
    case 'SPITTER':
      drawSpitter32(canvas, palette, f, dir, anim);
      break;
    case 'SPEWER':
      drawSpewer32(canvas, palette, f, dir, anim);
      break;
    case 'BEETLE':
      drawBeetle32(canvas, palette, f, dir, anim);
      break;
    case 'KNIGHT':
      drawKnight32(canvas, palette, f, dir, anim);
      break;
    case 'PRISM':
      drawPrism32(canvas, palette, f, dir, anim);
      break;
    case 'LANCER':
      drawLancer32(canvas, palette, f, dir, anim);
      break;
    case 'ORB':
      drawOrb32(canvas, palette, f, dir, anim);
      break;
    case 'MITE':
      drawMite32(canvas, palette, f, dir, anim);
      break;
    case 'CRAWLER':
      drawCrawler32(canvas, palette, f, dir, anim);
      break;
    case 'BLOATER':
      drawBloater32(canvas, palette, f, dir, anim);
      break;
    case 'BRUTE':
      drawBrute32(canvas, palette, f, dir, anim);
      break;
    case 'MATRON':
      drawMatron32(canvas, palette, f, dir, anim);
      break;
  }

  // SOLDIER 기본 철갑 팔레트 frame 0일 때는 IMG_2485.png / IMG_2486.png 원본과 1px의 오차도 없도록 추가 외곽선 패스를 생략한다
  if (!(archetype === 'SOLDIER' && (anim === 'IDLE' || anim === 'ATTACK') && f % 2 === 0)) {
    canvas.finalizeOutline();
  }
  return { width: canvas.size, height: canvas.size, data: canvas.data };
}

/** 하위 호환용 ASCII 실루엣 맵 추출기 */
export function getSpriteMap(archetype: SpriteArchetype): readonly string[] {
  const buf = renderSpritePixels(archetype, {
    primary: '#4f7fb8',
    secondary: '#2d4a6e',
    accent: '#f2c14e',
  });
  const rows: string[] = [];
  for (let y = 0; y < buf.height; y += 1) {
    let row = '';
    for (let x = 0; x < buf.width; x += 1) {
      const i = (y * buf.width + x) * 4;
      if (buf.data[i + 3] === 0) {
        row += '.';
      } else if (
        buf.data[i] === OUTLINE_RGB[0] &&
        buf.data[i + 1] === OUTLINE_RGB[1] &&
        buf.data[i + 2] === OUTLINE_RGB[2]
      ) {
        row += 'o';
      } else {
        row += 'p';
      }
    }
    rows.push(row);
  }
  return rows;
}

export function renderGemPixels(
  tier: 1 | 2 | 3,
  frame: number = 0
): { width: number; height: number; data: Uint8ClampedArray } {
  const size = 11;
  const data = new Uint8ClampedArray(size * size * 4);
  const f = Math.abs(Math.round(frame)) % 2;

  const setPx = (x: number, y: number, c: Rgb): void => {
    if (x < 0 || x >= size || y < 0 || y >= size) {
      return;
    }
    const i = (y * size + x) * 4;
    data[i] = c[0];
    data[i + 1] = c[1];
    data[i + 2] = c[2];
    data[i + 3] = 255;
  };

  const base: Rgb =
    tier === 3 ? [242, 172, 58] : tier === 2 ? [64, 224, 130] : [78, 212, 242];
  const dark: Rgb =
    tier === 3 ? [118, 58, 16] : tier === 2 ? [22, 92, 54] : [24, 78, 108];
  const light: Rgb = lighten(base, 0.42);
  const white: Rgb = [248, 252, 255];

  const radius = tier === 3 ? 4 : tier === 2 ? 3 : 2;
  const cx = 5;
  const cy = 5;

  for (let dy = -radius; dy <= radius; dy += 1) {
    const span = radius - Math.abs(dy);
    for (let dx = -span; dx <= span; dx += 1) {
      let col = base;
      if (dx < 0 && dy <= 0) {
        col = light;
      } else if (dx > 0 && dy >= 0) {
        col = dark;
      }
      setPx(cx + dx, cy + dy, col);
    }
  }
  setPx(cx, cy, white);
  setPx(cx - 1, cy - 1, white);
  if (tier >= 2) {
    setPx(cx, cy - 1, light);
    setPx(cx - 1, cy, light);
  }

  const snap = new Uint8ClampedArray(data);
  const isOp = (x: number, y: number): boolean =>
    x >= 0 && x < size && y >= 0 && y < size && snap[(y * size + x) * 4 + 3] > 0;
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      if (isOp(x, y)) {
        continue;
      }
      if (isOp(x - 1, y) || isOp(x + 1, y) || isOp(x, y - 1) || isOp(x, y + 1)) {
        setPx(x, y, OUTLINE_RGB);
      }
    }
  }

  if (f === 0) {
    setPx(cx - radius, cy - radius + 1, white);
  } else {
    setPx(cx + radius, cy - radius + 1, white);
    if (tier === 3) {
      setPx(cx, cy - radius - 1, white);
    }
  }

  return { width: size, height: size, data };
}

export function renderSlimeTilePixels(
  palette: FactionPalette,
  frame: number = 0
): { width: number; height: number; data: Uint8ClampedArray } {
  const size = 28;
  const data = new Uint8ClampedArray(size * size * 4);
  const f = Math.abs(Math.round(frame)) % 2;
  const pri = hexToRgb(palette.primary);
  const sec = hexToRgb(palette.secondary);
  const acc = hexToRgb(palette.accent);
  const crust = darken(sec, 0.45);
  const midPool = mixRgb(sec, acc, 0.38);
  const brightAcid = lighten(acc, 0.25);

  const cx = 13.5;
  const cy = 13.5;
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const dx = x - cx;
      const dy = y - cy;
      const angle = Math.atan2(dy, dx);
      const wobble =
        Math.sin(angle * 3 + 0.7) * 1.4 +
        Math.cos(angle * 5 - 1.1) * 0.9 +
        (f === 1 ? Math.sin(angle * 4) * 0.4 : 0);
      const dist = Math.hypot(dx, dy) + wobble;
      if (dist > 12.6) {
        continue;
      }
      let col: Rgb;
      let alpha = 215;
      if (dist > 11.2) {
        col = OUTLINE_RGB;
        alpha = 195;
      } else if (dist > 9.4) {
        col = crust;
      } else if (dist > 7.2) {
        col = sec;
      } else if (dist > 5.0) {
        col = pri;
      } else if (dist > 2.8) {
        col = midPool;
      } else {
        col = acc;
      }
      const i = (y * size + x) * 4;
      data[i] = col[0];
      data[i + 1] = col[1];
      data[i + 2] = col[2];
      data[i + 3] = alpha;
    }
  }

  const setBubble = (bx: number, by: number, c: Rgb): void => {
    const i = (by * size + bx) * 4;
    data[i] = c[0];
    data[i + 1] = c[1];
    data[i + 2] = c[2];
    data[i + 3] = 245;
  };
  if (f === 0) {
    setBubble(10, 11, brightAcid);
    setBubble(11, 11, [245, 255, 210]);
    setBubble(17, 15, brightAcid);
  } else {
    setBubble(10, 10, [245, 255, 210]);
    setBubble(16, 14, [245, 255, 210]);
    setBubble(12, 17, brightAcid);
  }

  return { width: size, height: size, data };
}

export function renderGroundTilePixels(): { width: number; height: number; data: Uint8ClampedArray } {
  const size = 64;
  const data = new Uint8ClampedArray(size * size * 4);
  const baseDark: Rgb = [14, 18, 26];
  const baseMid: Rgb = [18, 24, 34];
  const baseLight: Rgb = [23, 30, 42];
  const plateDark: Rgb = [20, 27, 39];
  const plateLight: Rgb = [28, 37, 52];
  const seam: Rgb = [10, 13, 20];

  const setPx = (x: number, y: number, c: Rgb): void => {
    const wx = ((x % size) + size) % size;
    const wy = ((y % size) + size) % size;
    const i = (wy * size + wx) * 4;
    data[i] = c[0];
    data[i + 1] = c[1];
    data[i + 2] = c[2];
    data[i + 3] = 255;
  };

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const wave =
        Math.sin((x + y) * ((Math.PI * 2) / 32)) * 0.25 +
        Math.cos((x - y * 2) * ((Math.PI * 2) / 64)) * 0.2;
      const col = wave < -0.1 ? baseDark : wave > 0.14 ? baseLight : baseMid;
      setPx(x, y, col);
    }
  }

  for (let py = 6; py < 22; py += 1) {
    for (let px = 8; px < 24; px += 1) {
      if (px === 8 || py === 6) {
        setPx(px, py, plateLight);
      } else if (px === 23 || py === 21) {
        setPx(px, py, seam);
      } else if ((px + py) % 4 === 0) {
        setPx(px, py, plateLight);
      } else {
        setPx(px, py, plateDark);
      }
    }
  }
  setPx(10, 8, [40, 52, 72]);
  setPx(21, 8, [40, 52, 72]);
  setPx(10, 19, [40, 52, 72]);
  setPx(21, 19, [40, 52, 72]);

  const craters = [
    { cx: 44, cy: 18, r: 4 },
    { cx: 26, cy: 46, r: 5 },
  ];
  for (const cr of craters) {
    for (let dy = -cr.r; dy <= cr.r; dy += 1) {
      for (let dx = -cr.r; dx <= cr.r; dx += 1) {
        const d = Math.hypot(dx, dy);
        if (d <= cr.r - 1.2) {
          setPx(cr.cx + dx, cr.cy + dy, seam);
        } else if (d <= cr.r + 0.3) {
          setPx(cr.cx + dx, cr.cy + dy, dx + dy < 0 ? seam : plateLight);
        }
      }
    }
  }

  for (let g = 0; g < size; g += 4) {
    setPx(g, 0, plateDark);
    setPx(0, g, plateDark);
  }

  return { width: size, height: size, data };
}
